<script setup lang="ts">
/**
 * A value shown as text, edited in place (`design/components/inline-edit.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/inline-edit.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import { Icon, afterRender, agentMember } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/inline-edit.module.css'
import Button from './Button.vue'
import Input from './Input.vue'

export interface InlineEditMessages {
  edit: (label: string) => string
  save: string
  cancel: string
}

export interface InlineEditProps {
  /**
   * The id of a description of the field and the edit control, as SettingsRow's.
   */
  ariaDescribedby?: string
  /**
   * The id of a label elsewhere that names the field, as SettingsRow's row label does.
   */
  ariaLabelledby?: string
  /**
   * Uncontrolled: whether the field is open when the member mounts. It takes no focus then.
   */
  defaultEditing?: boolean
  /**
   * The edit control is disabled. The value stays as it is.
   */
  disabled?: boolean
  /**
   * Controlled: whether the field is open. The app closes it once a save succeeds.
   */
  editing?: boolean
  /**
   * The app's message for a failed save, drawn under the field while it is open.
   */
  error?: string
  /**
   * Names the field ("Project name") and, through `messages.edit`, the edit control.
   */
  label: string
  maxLength?: number
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: InlineEditMessages
  /**
   * A save is in flight: the field is read-only, save is busy and cancel is disabled.
   */
  pending?: boolean
  /**
   * Drawn, muted, in place of an empty value, and the empty field's placeholder.
   */
  placeholder?: string
  /**
   * A blank text cannot be saved: the save control is disabled and Enter does nothing.
   */
  required?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * The saved value, drawn as text. The app owns it, so after a save it passes the new value.
   */
  value: string
  /**
   * Another element beside the member draws the value, as a page's `<h1>` does: the member draws
   * its edit control and its field, and the value describes the edit control without being
   * drawn. A page's `titleEdit` sets it.
   */
  valueHidden?: boolean
}

defineOptions({ name: 'InlineEdit', inheritAttrs: false })

const props = withDefaults(defineProps<InlineEditProps>(), {
  defaultEditing: false,
  disabled: false,
  editing: undefined,
  messages: () => ({ edit: (label) => `Edit ${label}`, save: 'Save', cancel: 'Cancel' }),
  pending: false,
  required: false,
  size: 'md',
  valueHidden: false,
})
const emit = defineEmits<{ commit: [value: string]; editingChange: [editing: boolean] }>()
const uid = useId()
const mirror = ref(props.defaultEditing)
const draft = ref(props.value)
const within = ref(false)
const root = useTemplateRef<HTMLElement>('root')
const current = computed(() => props.editing ?? mirror.value)
const valueId = computed(() => `${uid}-value`)
const errorId = computed(() => `${uid}-error`)
const refused = computed(() => props.required && draft.value.trim() === '')
const invalid = computed(() => current.value && props.error !== undefined && props.error !== '')
const fieldDescribedBy = computed(
  () =>
    [invalid.value ? errorId.value : undefined, props.ariaDescribedby]
      .filter((id) => id !== undefined)
      .join(' ') || undefined,
)
const editDescribedBy = computed(() =>
  props.ariaDescribedby === undefined ? valueId.value : `${valueId.value} ${props.ariaDescribedby}`,
)
const setOpen = computed(() => (next: boolean) => {
  mirror.value = next
  emit('editingChange', next)
})
const open = computed(() => () => {
  draft.value = props.value
  setOpen.value(true)
})
const cancel = computed(() => () => {
  if (!props.pending) setOpen.value(false)
})
const commit = computed(() => () => {
  if (props.pending || refused.value) return
  if (draft.value === props.value) {
    setOpen.value(false)
    return
  }
  emit('commit', draft.value)
  if (props.editing === undefined) setOpen.value(false)
})
const onKey = computed(() => (event: KeyboardEvent) => {
  if (event.key === 'Escape') {
    event.preventDefault()
    cancel.value()
    return
  }
  if (event.key === 'Enter' && event.target instanceof HTMLInputElement && !event.isComposing) {
    event.preventDefault()
    commit.value()
  }
})
const leave = computed(() => (event: FocusEvent) => {
  const next = event.relatedTarget
  if (next instanceof Node && !(root.value?.contains(next) ?? false)) within.value = false
})
const saveText = computed(() => (text: string) => {
  if (!current.value) throw new Error('The field is closed: edit opens it.')
  if (props.pending) throw new Error('A save is in flight.')
  if (props.required && text.trim() === '') throw new Error('The field is required.')
  draft.value = text
  if (text === props.value) {
    setOpen.value(false)
    return
  }
  emit('commit', text)
  if (props.editing === undefined) setOpen.value(false)
})
const effect1 = () => {
  current.value
    ? ((draft.value = props.value),
      afterRender(() => {
        const input = root.value?.querySelector('input')
        input?.focus()
        input?.select()
      }))
    : within.value && afterRender(() => root.value?.querySelector('button')?.focus())
}
watch(() => current.value, effect1, { flush: 'post' })
const effect2 = () => {
  !props.pending && current.value && within.value && root.value?.querySelector('input')?.focus()
}
watch(() => props.pending, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'InlineEdit',
    element: () => root.value?.querySelector('input') ?? root.value?.querySelector('button'),
    state: () => ({
      value: props.value,
      editing: current.value,
      pending: props.pending,
      error: invalid.value ? (props.error ?? '') : '',
      disabled: props.disabled,
    }),
    actions: {
      edit: () =>
        (() => {
          if (!current.value) open.value()
        })(),
      save: { argument: 'text', run: (value) => saveText.value(value) },
      cancel: () =>
        (() => {
          if (props.pending) throw new Error('A save is in flight.')
          if (current.value) setOpen.value(false)
        })(),
    },
    withholds: () => root.value,
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.root"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-editing="current ? '' : undefined"
    data-member="inline-edit"
    @focusin="within = true"
    @focusout="leave($event)"
  >
    <!-- panel -->
    <div
      v-if="current"
      :class="styles.panel"
      data-inline-edit-part="panel"
      @keydown="onKey($event)"
    >
      <!-- row -->
      <div :class="styles.row">
        <!-- field -->
        <div :class="styles.field">
          <Input
            :size="size"
            :value="draft"
            :placeholder="placeholder"
            :maxLength="maxLength"
            :readOnly="pending"
            :disabled="disabled"
            :invalid="invalid"
            :aria-label="ariaLabelledby === undefined ? label : undefined"
            :aria-labelledby="ariaLabelledby"
            :aria-describedby="fieldDescribedBy"
            :aria-required="required ? true : undefined"
            @change="draft = $event"
          />
        </div>
        <Button
          variant="soft"
          tone="accent"
          :size="size"
          :iconOnly="true"
          icon="confirm"
          :label="messages.save"
          :loading="pending"
          :disabled="disabled || refused"
          @click="commit()"
        />
        <Button
          variant="ghost"
          tone="neutral"
          :size="size"
          :iconOnly="true"
          icon="close"
          :label="messages.cancel"
          :disabled="disabled || pending"
          @click="cancel()"
        />
      </div>
      <!-- status -->
      <div aria-live="polite">
        <!-- error -->
        <p v-if="invalid" :class="styles.error" :id="errorId">
          <!-- glyph -->
          <span :class="styles.glyph">
            <Icon name="error" size="sm" />
          </span>
          {{ error }}
        </p>
      </div>
    </div>
    <template v-else>
      <!-- value -->
      <span
        :class="styles.value"
        :id="valueId"
        :hidden="valueHidden"
        :data-placeholder="value === '' ? '' : undefined"
      >
        {{ (value === '' ? placeholder : value) ?? '' }}
      </span>
      <Button
        variant="ghost"
        tone="neutral"
        :size="size"
        :iconOnly="true"
        icon="edit"
        :label="messages.edit(label)"
        :disabled="disabled"
        :aria-describedby="editDescribedBy"
        @click="open()"
      />
    </template>
  </div>
</template>
